// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        bool ok;
        try VaultAdapter(address(c)).proxiableUUID{gas: gasleft()}() returns (bytes32 v) {
            ok = (v == 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
